__NUXT_JSONP__("/desarrollo-sostenible/noticias/ethos_advierte_tres_aspectos_claves_que_explican_la_crisis_energetica_en_mexico", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{post:{slug:"ethos_advierte_tres_aspectos_claves_que_explican_la_crisis_energetica_en_mexico",title:"Ethos advierte tres aspectos claves que explican la crisis energética en México",date:"2023-06-26T15:52:28.782Z",img:"https:\u002F\u002Fucarecdn.com\u002F62e08703-70d7-4bca-a038-8c12356539dd\u002F","img-alt":"Torres de electricidad",autor:"Gabriela Francovigh, Energía Estratégica",link:"https:\u002F\u002Fwww.energiaestrategica.com\u002Fethos-advierte-tres-aspectos-claves-que-explican-la-crisis-energetica-en-mexico\u002F",category:"desarrollo-sostenible",extracto:"Especialistas del think tank alertan que el estado de emergencia energética emitido por el CENACE fue el desenlace de medidas del Gobierno basadas en ideales políticos de \"alcanzar la soberanía energética\" y no de planeación estratégica.",toc:[],body:{type:"root",children:[{type:b,tag:e,props:{},children:[{type:a,value:"Por las fuertes olas de calor que atraviesa el país, el pasado 20 de junio se alcanzó un pico histórico de demanda bruta de electricidad, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.cenace.gob.mx\u002FDocs\u002FEstadoOperativoSEN\u002F2023\u002F2023-06-20__SIN23-0126.pdf",rel:[g,h,i],target:j},children:[{type:a,value:"alcanzando los 52,823 MW."}]},{type:a,value:" Esta cifra fue un 9% superior al máximo registrado en el año 2022, lo cual preocupa el sector teniendo en cuenta que el verano apenas comienza."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"En diálogo con "},{type:b,tag:d,props:{},children:[{type:a,value:"Energía Estratégica, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.linkedin.com\u002Fin\u002Fsebastianguzmand\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"Sebastián Guzmán,"}]},{type:a,value:" coordinador de Ciudades del Futuro"}]},{type:a,value:" en"},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.ethos.org.mx\u002F",rel:[g,h,i],target:j},children:[{type:a,value:l},{type:b,tag:d,props:{},children:[{type:a,value:"Ethos Innovación en Políticas Públicas"}]},{type:a,value:","}]},{type:a,value:" explica que este pico en la demanda es el “efecto dominó” de un conjunto de malas decisiones sobre la cual se ha estructurado la política energética del Gobierno actual."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Según el especialista, esta crisis energética se explica por "},{type:b,tag:d,props:{},children:[{type:a,value:"3 razones claves:"}]}]},{type:a,value:c},{type:b,tag:"ol",props:{},children:[{type:a,value:c},{type:b,tag:"li",props:{},children:[{type:a,value:l},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"La cancelación de mecanismos de inversión para el desarrollo de proyectos de generación de energía"}]}]}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Entre 2019 y 2022 la inversión en el sector energético nacional disminuyó en un 72% durante este sexenio acumulando apenas $2,800 millones de dólares, mientras que entre 2014-2018 los montos de inversión en el sector alcanzaron los "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002Fel-sextante",rel:[g,h,i],target:j},children:[{type:a,value:"$10,000 millones de dólares."}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Según Guzmán, "},{type:b,tag:d,props:{},children:[{type:a,value:"esta reducción se vincula con la cancelación de las subastas de largo plazo,"}]},{type:a,value:" las cuales funcionaban como instrumentos para el desarrollo de proyectos de generación principalmente de energías renovables."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Estas limitaciones en materia de generación eléctrica muestran una tendencia que ha comenzado a rebasar el margen de reserva de energía que de acuerdo con el "},{type:b,tag:d,props:{},children:[{type:a,value:"Código de Red debe ser del 13% como mínimo."}]},{type:a,value:" En efecto, el pasado 20 junio el estado de emergencia reportado por el "},{type:b,tag:d,props:{},children:[{type:a,value:"CENACE"}]},{type:a,value:" fue porque el margen de reserva operativa era menor al 6%."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"«En condiciones operativas y de demanda normales, México cuenta con la electricidad suficiente para dar cobertura, el problema está, en que actualmente las ondas de calor que han azotado al país no son condiciones normales, lo que ha provocado un mayor consumo de energía. En regiones como la "},{type:b,tag:d,props:{},children:[{type:a,value:"Zona Metropolitana del Valle de México"}]},{type:a,value:", por ejemplo, se han registrado temperaturas superiores a los 35 ºC y ha provocado que se adquieran equipos de aire acondicionado para tener un mayor confort térmico.  Esto es uno de los principales factores del incremento desmesurado de la demanda de electricidad actual», destaca el experto de "},{type:b,tag:d,props:{},children:[{type:a,value:"Ethos"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"«Desafortunadamente el gobierno jamás se imagino que ocurriría y no se tomaron las precauciones pertinentes para hacerle frente en caso de que sucediera, aunado a que el verano apenas comienza y esta tendencia tanto de aumento en la temperatura como de demanda de electricidad, podría mantenerse e incluso incrementarse. Es ahí donde está la gravedad de este problema y la gran responsabilidad del gobierno», agrega."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"2. "},{type:b,tag:d,props:{},children:[{type:a,value:"Cambio metodológico injustificado en el diseño de documentos de planeación estratégica del sector energético"}]}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.gob.mx\u002Fsener\u002Farticulos\u002Fprograma-de-desarrollo-del-sistema-electrico-nacional-2023-2037",rel:[g,h,i],target:j},children:[{type:a,value:"El PRODESEN 2023-2037"}]},{type:a,value:" fue muy criticado por modificar los criterios metodológicos de participación de generación de energías limpias, "},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.energiaestrategica.com\u002Falertan-que-el-cumplimiento-de-las-metas-previstas-por-el-prodesen-a-traves-de-ciclos-combinados-es-ficticio\u002F",rel:[g,h,i],target:j},children:[{type:a,value:"donde se “alteraron” datos para “inflar” las cifras y alcanzar las metas de descarbonización."}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Además, Guzmán explica: «El PRODESEN reveló las deficiencias en el desarrollo de la "},{type:b,tag:d,props:{},children:[{type:a,value:"Red Nacional de Transmisión y Distribución"}]},{type:a,value:", en donde, se había definido la necesidad de desarrollar aproximadamente 318 proyectos para estos dos sectores –los cuales hay que recordar son competencia única del sector público, es decir de la "},{type:b,tag:d,props:{},children:[{type:a,value:"CFE"}]},{type:a,value:",– y"},{type:b,tag:f,props:{href:"https:\u002F\u002Fwww.energiaestrategica.com\u002Flos-diez-puntos-clave-del-prodesen-2023-2037-segun-el-instituto-mexicano-para-la-competitividad\u002F",rel:[g,h,i],target:j},children:[{type:a,value:" de esos 318 únicamente se han construido 30 para 2023″. "}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Para el experto, este fenómeno ha generado “cuellos de botella” en 3 principales regiones del país, en donde la reserva operativa de energía se ve limitada. Estas regiones son el: "},{type:b,tag:d,props:{},children:[{type:a,value:"Noroeste"}]},{type:a,value:" (principalmente estados como Sonora y Chihuahua), "},{type:b,tag:d,props:{},children:[{type:a,value:"la península de Yucatán"}]},{type:a,value:" (principalmente estados como Yucatán y Tabasco) y finalmente, la región de "},{type:b,tag:d,props:{},children:[{type:a,value:"Baja California tanto Norte como Sur."}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Cabe destacar que ninguna de estas zonas forman parte del "},{type:b,tag:d,props:{},children:[{type:a,value:"Sistema Interconectado Nacional (SIN),"}]},{type:a,value:" por lo que tienen aún más limitaciones en cuanto a su disponibilidad de electricidad."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Si bien el presidente "},{type:b,tag:d,props:{},children:[{type:a,value:"Andrés Manuel López Obrador"}]},{type:a,value:" en la mañanera del lunes pasado descartó que se puedan producir apagones, Guzmán advierte que «ya se ha reportado este tipo de eventos en estas regiones y son muy factibles que puedan continuar presentándose»."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"3. "},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{},children:[{type:a,value:"La cancelación del Horario de Verano y sus verdaderas consecuencias sociales."}]}]}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Históricamente la razón de la "},{type:b,tag:d,props:{},children:[{type:a,value:"creación del Horario de Verano"}]},{type:a,value:" había sido la de aprovechar más la luz del sol para utilizar menos la energía eléctrica en los hogares y edificios de trabajo. Dicho programa fue creado por el ex-presidente "},{type:b,tag:d,props:{},children:[{type:a,value:"Ernesto Zedillo Ponce de León,"}]},{type:a,value:" uno de los principales detractores de las medidas de política económica emprendidas por el actual gobierno."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Por estos motivos, de acuerdo a Guzmán, bajo «una evaluación más de percepción social que técnico-económica» AMLO argumentó que no se han producido los ahorros en energía que se prometieron cuando entró en vigor en 1996."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"«Las estimaciones de ahorro de electricidad reportadas por el Horario de Verano oscilaban entre el 1 y 3% anual y su variación dependía de la región del país –ya que la demanda de energía eléctrica no es homogénea– por lo que su efectividad era mayor en algunas regiones del país, pero en lo general, cumplía su propósito de mejorar la gestión de la demanda energética durante esa época del año», explica."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"«Bajo la situación actual de estrés del "},{type:b,tag:d,props:{},children:[{type:a,value:"Sistema Eléctrico Nacional (SEN)"}]},{type:a,value:" por el incremento en la demanda y teniendo en cuenta que la temporada de verano apenas comienza y con ello, se suma un incremento adicional en la demanda de entre un 8-5%, la aportación que el Horario de Verano hubiera representado una ayuda importante para mejorar las condiciones alarmantes en las cuales se encuentra el sector energético nacional», añade."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"En tanto a las consecuencias sociales, el especialista explica: “Si empieza a haber apagones las zonas que se van a priorizar para revertir la situación son las zonas urbanas o turísticas, y se van a desanter las zonas más alejadas de la urbe donde viven la población más vulnerable. Estas son cuestiones que nunca se visualizaron cuando el actual gobierno diseñó la política energética actual»."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fethos_advierte_tres_aspectos_claves_que_explican_la_crisis_energetica_en_mexico",extension:".md",createdAt:m,updatedAt:m}}],fetch:{},mutations:[]}}("text","element","\n","strong","p","a","nofollow","noopener","noreferrer","_blank","em"," ","2023-09-12T15:29:17.055Z")));